    /**
     * Method to retrieve the Order via an FindOrderQuery
     * @return 	query	FindOrderQuery
     */
    @SuppressWarnings("unused")
    public Order find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Order - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Orders
     *
     * @param	query	FindAllOrderQuery 
     * @return 	List<Order> 
     */
    @SuppressWarnings("unused")
    public List<Order> findAll( FindAllOrderQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Order - {0}", exc.getMessage() );
    	}
    	return null;
    }


